// Shift to 2, 3, and 4 days ago. Direct R2 access is much faster.
const datesToCheck = [];
const today = new Date(); 
for (let i = 2; i <= 4; i++) {
    const date = new Date(today);
    date.setUTCDate(date.getUTCDate() - i);
    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const day = String(date.getUTCDate()).padStart(2, '0');
    datesToCheck.push({
        json: {
            dateString: `${year}${month}${day}`,
            friendlyDate: date.toISOString().split('T')[0]
        }
    });
}
return datesToCheck;

const Redis = require('ioredis');
let redis;
const QUEUE_KEY = 'intel:queue:archive'; 
const PROCESSED_HASH_KEY = 'intel:kill:data';

const items = $input.all();
const killsToCheck = []; 

for (const item of items) {
    const data = item.json;

    // Guard against any leftover HTML or error objects
    if (data.data && typeof data.data === 'string' && data.data.includes('<html>')) {
        continue;
    }

    // Handle zKill ID:Hash objects from the R2 bucket
    for (const [killId, hash] of Object.entries(data)) {
        const numericKillId = parseInt(killId, 10);
        if (numericKillId && typeof hash === 'string') {
            killsToCheck.push({ kill_id: numericKillId, hash: hash });
        }
    }
}

if (killsToCheck.length === 0) {
    return [{ json: { status: 'empty', reason: 'No valid data found in R2 bucket for these dates.' } }];
}

try {
    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });
    const checkPipeline = redis.pipeline();
    killsToCheck.forEach(k => checkPipeline.hexists(PROCESSED_HASH_KEY, String(k.kill_id)));
    const results = await checkPipeline.exec();

    const killsToQueue = [];
    results.forEach((res, index) => {
        if (res[1] === 0) killsToQueue.push(killsToCheck[index]);
    });

    if (killsToQueue.length > 0) {
        const queuePipeline = redis.pipeline();
        for (const kill of killsToQueue) {
            queuePipeline.rpush(QUEUE_KEY, JSON.stringify(kill));
        }
        await queuePipeline.exec();
    }

    return [{ json: { new_kills_queued: killsToQueue.length, total_checked: killsToCheck.length } }];
} finally {
    if (redis) await redis.quit();
}

const Redis = require('ioredis');
const DAYS_TO_KEEP = 30;
const TTL_SECONDS = 31 * 24 * 60 * 60;
const BATCH_SIZE = 500;
const REDIS_CONFIG = { host: 'redis', port: 6379, db: 0, connectTimeout: 5000 };

const comprehensivelyDelete = (killmails, pipeline, report, type) => {
    if (!Array.isArray(killmails) || killmails.length === 0) return;
    const idsToDelete = killmails.map(km => String(km.killmail_id));
    pipeline.hdel('intel:kill:data', ...idsToDelete);
    pipeline.zrem('intel:kills:all', ...idsToDelete);
    pipeline.zrem('intel:kills:24h_stats', ...idsToDelete);

    const removeAndExpire = (key, id) => {
        pipeline.zrem(key, id);
        pipeline.expire(key, TTL_SECONDS);
    };

    for (const km of killmails) {
        const killIdStr = String(km.killmail_id);
        if (type === 'age') report.summary.pruned_by_age++;
        if (km.space_type) removeAndExpire(`intel:kills:space:${km.space_type}`, killIdStr);
        if (km.solar_system_id) removeAndExpire(`intel:kills:system:${km.solar_system_id}`, killIdStr);
    }
};

const redis = new Redis(REDIS_CONFIG);
const report = { status: 'started', summary: { pruned_by_age: 0, seen_killmails_cleared: false } };

try {
    const cutoffScore = Math.floor((Date.now() - (DAYS_TO_KEEP * 24 * 60 * 60 * 1000)) / 1000);
    const idsToPrune = await redis.zrangebyscore('intel:kills:all', 0, cutoffScore);

    if (idsToPrune.length > 0) {
        for (let i = 0; i < idsToPrune.length; i += BATCH_SIZE) {
            const batchIds = idsToPrune.slice(i, i + BATCH_SIZE);
            const batchDataJson = await redis.hmget('intel:kill:data', ...batchIds);
            const killmailsInBatch = batchDataJson.map(json => json ? JSON.parse(json) : null).filter(Boolean);
            const delPipe = redis.pipeline();
            comprehensivelyDelete(killmailsInBatch, delPipe, report, 'age');
            await delPipe.exec();
        }
    }

    await redis.del('r2z2:seen_killmails');
    report.summary.seen_killmails_cleared = true;
    report.status = 'success';
} catch (e) {
    report.status = 'error';
    report.error = e.message;
} finally {
    await redis.quit();
}

return [{ json: report }];
